// src/components/ViewSendMessages.jsx
import React, { useEffect, useState } from "react";
import "./CSS/ViewSendMessages.css";
import { useNavigate, useLocation } from "react-router-dom";
import { IoArrowBack } from "react-icons/io5";
import { IoIosSend } from "react-icons/io";
import { MdAttachFile } from "react-icons/md";

function ViewSendMessages() {
  const navigate = useNavigate();
  const location = useLocation();
  const peerEmail = location.state?.peerEmail || "";
  const userEmail = localStorage.getItem("email");

  const [message, setMessage] = useState("");
  const [chat, setChat] = useState([]);
  const [status, setStatus] = useState("");

  useEffect(() => {
    if (!peerEmail || !userEmail) {
      alert("Missing user info.");
      navigate("/dashboard");
      return;
    }

    fetch("http://127.0.0.1:5000/get-conversation", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ user1: userEmail, user2: peerEmail }),
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.success) setChat(data.messages);
      })
      .catch((err) => {
        console.error("Conversation fetch failed:", err);
        setStatus("Failed to load chat.");
      });
  }, [peerEmail, userEmail, navigate]);

  const handleSendMessage = async () => {
    if (!message.trim()) return;

    const newMessage = {
      sender: userEmail,
      receiver: peerEmail,
      message: message.trim(),
    };

    try {
      const res = await fetch("http://127.0.0.1:5000/send-message", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newMessage),
      });

      const result = await res.json();
      if (result.success) {
        const now = new Date();
        const msgObj = {
          from: userEmail,
          to: peerEmail,
          content: message.trim(),
          time: now.toLocaleTimeString(),
        };
        setChat((prev) => [...prev, msgObj]);
        setMessage("");
      } else {
        setStatus("Message failed.");
      }
    } catch (err) {
      console.error("Send error:", err);
      setStatus("Error sending message.");
    }
  };

  return (
    <div className="vsm-container">
      <header className="vsm-header">
        <button className="vsm-back" onClick={() => navigate("/dashboard")}>
          <IoArrowBack size={24} />
        </button>
        <div className="vsm-user">
          <p className="vsm-name">Chat with</p>
          <p className="vsm-email">{peerEmail}</p>
        </div>
      </header>

      <div className="vsm-chat-area">
        {chat.length === 0 ? (
          <p className="vsm-placeholder">No messages yet.</p>
        ) : (
          chat.map((msg, idx) => (
            <div
              key={idx}
              className={`vsm-message ${
                msg.sender === userEmail ? "vsm-sent" : "vsm-received"
              }`}
            >
              <div className="vsm-bubble">
                <p className="vsm-text">{msg.message || msg.content}</p>
                <p className="vsm-time">
                  {msg.time || `${msg.date} ${msg.time}`}
                </p>
              </div>
            </div>
          ))
        )}
      </div>

      {status && <p className="vsm-status">{status}</p>}

      <footer className="vsm-footer">
        <button className="vsm-attach">
          <MdAttachFile size={20} />
        </button>
        <input
          type="text"
          className="vsm-input"
          placeholder="message"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
        />
        <button className="vsm-send" onClick={handleSendMessage}>
          <IoIosSend size={22} />
        </button>
      </footer>
    </div>
  );
}

export default ViewSendMessages;
